# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Legendre polynomial of the first kind, P_n(x), elementwise.

Reference semantics (matching torch.special.legendre_polynomial_p and the
generic KernelGen baseline):
    P_0(x) = 1
    P_1(x) = x
    i * P_i(x) = (2i - 1) * x * P_{i-1}(x) - (i - 1) * P_{i-2}(x)
with the degree truncated toward zero (m = int(n)); m < 0 yields 0, and only
float32 input is accepted, because ATen's autograd kernel dispatches floating
types and the baseline asserts float32.

Design notes (gcu400 adaptation, same family as special_chebyshev_polynomial_w):
  * The generic baseline runs the Bonnet recurrence as a 254-step
    `tl.static_range` unroll behind `pointwise_dynamic`; the resulting ~1.6 MB
    fatbin executes fine on the tiny quick-test tile but raises a Sip
    exception (KMD aborts the context, host process core dumps) as soon as a
    large shape selects the 4096-element grid-stride variant. The unrolled
    recurrence is therefore replaced by a 3-step compile-time unroll plus a
    guarded dynamic tail (`if steps > _UNROLL_ORDER`), which is the proven
    shape for dynamic recurrences on this toolchain (finer tiles or unguarded
    zero-trip loops have miscompiled before).
  * One flat 1-D grid-strided launch per call: small tiles (1024) with a
    persistent grid of at most 48 CTAs, an 8192 fat tile for >= 2**20
    elements (16384 with num_warps=1 fails to compile in PassManager).
  * Three degree modes chosen from cheap metadata only:
        N_MODE 0 : host-known Python scalar degree (passed by value),
        N_MODE 1 : single-element degree tensor (scalar load),
        N_MODE 2 : per-element degree tensor (tile max bound + per-lane mask);
    int64 degree tensors are narrowed to int32 on the host (the recurrence
    stays far below that range) so no 64-bit loads reach the kernel.
  * A strided fallback covers non-contiguous / broadcasting inputs.
  * Degrees above 255 clamp like the baseline loop bound (P_255); fp32
    overflows beyond that agree with ATen float32 anyway.
  * no framework arithmetic produces the result and no input is mutated.
"""

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

_BLOCK = 1024
_NUM_WARPS = 1
_MAX_GRID = 65535
_BIG_TOTAL = 1 << 20
# 大 shape 用 8192 的 fat tile 打满 DTE；中小 shape 保持 1024（同族
# special_chebyshev_polynomial_w 的实测结论：更细的 tile 会让动态递推
# miscompile，16384 配 num_warps=1 编译失败，故上限取 8192）。
_TILE_BIG = 8192
# GCU400 的 SIP 拓扑对应 24 个物理 SIP；48 个 CTA 是持久网格的经验上限，
# 更多 CTA 只会增加调度成本，核内用跨步循环补齐 tile。
_GRID_SIPS = 48

# Baseline parity: the generic kernel unrolls degrees 2..255, so degrees are
# clamped to P_255 here as well.
_MAX_STEPS = tl.constexpr(255)
# 常见阶数编译期展开：degree 是运行期标量时循环上界无法静态展开，
# 固定展开 _UNROLL_ORDER 步，用掩码屏蔽多余的递推。
_UNROLL_ORDER = tl.constexpr(3)


def _pick(numel):
    """(BLOCK, grid.x) for a launch over `numel` elements.

    仅大 shape 换用 fat tile；grid 固定不超过 _GRID_SIPS，剩余 tile 由 kernel
    内的跨步循环消费，num_programs 只影响运行时跨步长度。
    """
    block = _BLOCK if numel < _BIG_TOTAL else _TILE_BIG
    grid = min((numel + block - 1) // block, _GRID_SIPS)
    return block, grid


@triton.jit(do_not_specialize=["numel", "degree"])
def _p_flat_kernel(
    X,
    N,
    OUT,
    numel,
    degree,
    N_MODE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    nchunk = tl.cdiv(numel, step)
    start0 = pid * BLOCK
    rng = tl.arange(0, BLOCK)

    for c in range(0, nchunk):
        offs = start0 + c * step + rng
        mask = offs < numel
        x = tl.load(X + offs, mask=mask, other=0.0)
        zero = 0.0
        one = tl.full((BLOCK,), 1.0, x.dtype)

        if N_MODE == 2:
            # Per-element degrees: bound the loop by the tile maximum.
            m = tl.load(N + offs, mask=mask, other=0).to(tl.int32)
            steps = tl.minimum(
                tl.maximum(tl.max(tl.where(mask, m, 0), axis=0), 0), _MAX_STEPS
            )
            p_prev2 = one
            p_prev1 = x
            for k in tl.static_range(2, _UNROLL_ORDER + 1):
                p_curr = ((2.0 * k - 1.0) * x * p_prev1 - (k - 1.0) * p_prev2) / k
                active = m >= k
                p_prev2 = tl.where(active, p_prev1, p_prev2)
                p_prev1 = tl.where(active, p_curr, p_prev1)
            # 超过展开上限的阶数仍按动态循环补齐；零行程循环在本工具链上有
            # miscompile 前科，必须用 if 守卫（laguerre 教训）。
            if steps > _UNROLL_ORDER:
                for kk in range(_UNROLL_ORDER + 1, steps + 1):
                    p_curr = (
                        (2.0 * kk - 1.0) * x * p_prev1 - (kk - 1.0) * p_prev2
                    ) / kk
                    active = m >= kk
                    p_prev2 = tl.where(active, p_prev1, p_prev2)
                    p_prev1 = tl.where(active, p_curr, p_prev1)
            res = tl.where(m < 0, zero, tl.where(m == 0, one, p_prev1))
        else:
            if N_MODE == 1:
                # One degree for the whole launch (0-dim / 1-element tensor).
                m = tl.load(N).to(tl.int32)
            else:
                # Host-known degree.
                m = degree
            steps = tl.minimum(tl.maximum(m, 0), _MAX_STEPS)
            p_prev2 = one
            p_prev1 = x
            for k in tl.static_range(2, _UNROLL_ORDER + 1):
                p_curr = ((2.0 * k - 1.0) * x * p_prev1 - (k - 1.0) * p_prev2) / k
                active = steps >= k
                p_prev2 = tl.where(active, p_prev1, p_prev2)
                p_prev1 = tl.where(active, p_curr, p_prev1)
            if steps > _UNROLL_ORDER:
                for kk in range(_UNROLL_ORDER + 1, steps + 1):
                    p_curr = (
                        (2.0 * kk - 1.0) * x * p_prev1 - (kk - 1.0) * p_prev2
                    ) / kk
                    p_prev2 = p_prev1
                    p_prev1 = p_curr
            res = tl.where(m < 0, zero, tl.where(m == 0, one, p_prev1))

        tl.store(OUT + offs, res, mask=mask)


@triton.jit
def _p_strided_kernel(
    X,
    N,
    OUT,
    numel,
    degree,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    xs0,
    xs1,
    xs2,
    xs3,
    xs4,
    xs5,
    xs6,
    xs7,
    ns0,
    ns1,
    ns2,
    ns3,
    ns4,
    ns5,
    ns6,
    ns7,
    N_MODE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    nchunk = tl.cdiv(numel, step)
    start0 = pid * BLOCK
    rng = tl.arange(0, BLOCK)

    dims = (d0, d1, d2, d3, d4, d5, d6, d7)
    xstr = (xs0, xs1, xs2, xs3, xs4, xs5, xs6, xs7)
    nstr = (ns0, ns1, ns2, ns3, ns4, ns5, ns6, ns7)

    for c in range(0, nchunk):
        offs = start0 + c * step + rng
        mask = offs < numel

        rem = offs
        xoff = tl.zeros((BLOCK,), tl.int32)
        noff = tl.zeros((BLOCK,), tl.int32)
        # 静态展开保证 i 是编译期下标（运行期下标无法索引 python 元组），
        # 维度在 host 侧已消毒为 >= 1，无需标量 tl.where。
        for i in tl.static_range(7, -1, -1):
            d = dims[i]
            cc = rem % d
            rem = rem // d
            xoff += cc * xstr[i]
            noff += cc * nstr[i]

        x = tl.load(X + xoff, mask=mask, other=0.0)
        zero = 0.0
        one = tl.full((BLOCK,), 1.0, x.dtype)

        if N_MODE == 2:
            m = tl.load(N + noff, mask=mask, other=0).to(tl.int32)
            steps = tl.minimum(
                tl.maximum(tl.max(tl.where(mask, m, 0), axis=0), 0), _MAX_STEPS
            )
            p_prev2 = one
            p_prev1 = x
            for k in tl.static_range(2, _UNROLL_ORDER + 1):
                p_curr = ((2.0 * k - 1.0) * x * p_prev1 - (k - 1.0) * p_prev2) / k
                active = m >= k
                p_prev2 = tl.where(active, p_prev1, p_prev2)
                p_prev1 = tl.where(active, p_curr, p_prev1)
            if steps > _UNROLL_ORDER:
                for kk in range(_UNROLL_ORDER + 1, steps + 1):
                    p_curr = (
                        (2.0 * kk - 1.0) * x * p_prev1 - (kk - 1.0) * p_prev2
                    ) / kk
                    active = m >= kk
                    p_prev2 = tl.where(active, p_prev1, p_prev2)
                    p_prev1 = tl.where(active, p_curr, p_prev1)
            res = tl.where(m < 0, zero, tl.where(m == 0, one, p_prev1))
        else:
            if N_MODE == 1:
                m = tl.load(N).to(tl.int32)
            else:
                m = degree
            steps = tl.minimum(tl.maximum(m, 0), _MAX_STEPS)
            p_prev2 = one
            p_prev1 = x
            for k in tl.static_range(2, _UNROLL_ORDER + 1):
                p_curr = ((2.0 * k - 1.0) * x * p_prev1 - (k - 1.0) * p_prev2) / k
                active = steps >= k
                p_prev2 = tl.where(active, p_prev1, p_prev2)
                p_prev1 = tl.where(active, p_curr, p_prev1)
            if steps > _UNROLL_ORDER:
                for kk in range(_UNROLL_ORDER + 1, steps + 1):
                    p_curr = (
                        (2.0 * kk - 1.0) * x * p_prev1 - (kk - 1.0) * p_prev2
                    ) / kk
                    p_prev2 = p_prev1
                    p_prev1 = p_curr
            res = tl.where(m < 0, zero, tl.where(m == 0, one, p_prev1))

        tl.store(OUT + offs, res, mask=mask)


_DIMS = 8


def _strided_launch(x, n, out, numel, degree, n_mode, block, warps):
    """General (non-contiguous / broadcasting) fallback."""
    shape = out.shape
    nd = len(shape)
    if nd > _DIMS:
        raise ValueError("special_legendre_polynomial_p: too many dimensions")
    pad = _DIMS - nd
    # 维度消毒为 >= 1（0 元输入早已提前返回），kernel 内免做标量 where。
    dims = [1] * pad + [max(1, int(s)) for s in shape]
    xs = [0] * pad + [int(s) for s in x.stride()]
    ns = [0] * pad + [int(s) for s in n.stride()]
    grid = (min((numel + block - 1) // block, _MAX_GRID),)
    _p_strided_kernel[grid](
        x,
        n,
        out,
        numel,
        degree,
        *dims,
        *xs,
        *ns,
        N_MODE=n_mode,
        BLOCK=block,
        num_warps=warps,
    )


def _run(x, n, out=None):
    dtype = x.dtype
    if dtype is not torch.float32:
        raise ValueError(
            "special_legendre_polynomial_p only supports float32, " f"got {dtype}"
        )

    if isinstance(n, torch.Tensor):
        # Pointwise semantics: the result covers the broadcast of x and n.
        out_shape = torch.broadcast_shapes(x.shape, n.shape)
    else:
        out_shape = x.shape
    numel = 1
    for s in out_shape:
        numel *= s
    if out is None:
        out = torch.empty(out_shape, dtype=dtype, device=x.device)
    if numel == 0:
        return out

    block, grid_n = _pick(numel)
    warps = _NUM_WARPS
    grid = (grid_n,)

    if isinstance(n, torch.Tensor):
        if n.dtype is torch.int64:
            # 64-bit data is not accepted by every backend's kernels; narrow the
            # degree to int32 (the recurrence stays far below its range).
            n = n.to(torch.int32)
        if n.numel() == 1:
            n_mode = 1
        else:
            n_mode = 2
            # NOTE: the per-lane-degree kernel keeps the original geometry
            # (small tile, four warps), mirroring the chebyshev family note.
            block = _BLOCK
            grid = (min(triton.cdiv(numel, _BLOCK), _MAX_GRID),)
            warps = 4
        if n_mode == 1 and x.is_contiguous():
            _p_flat_kernel[grid](
                x, n, out, numel, 0, N_MODE=1, BLOCK=block, num_warps=warps
            )
        elif (
            n_mode == 2
            and x.is_contiguous()
            and n.is_contiguous()
            and n.shape == out_shape
        ):
            _p_flat_kernel[grid](
                x, n, out, numel, 0, N_MODE=2, BLOCK=block, num_warps=warps
            )
        else:
            xb = x if x.shape == out_shape else x.expand(out_shape)
            nb = n if n.shape == out_shape else n.expand(out_shape)
            # same restriction as the flat path: N_MODE=2 only compiles with
            # the small tile and four warps.
            _strided_launch(
                xb,
                nb,
                out,
                numel,
                0,
                n_mode,
                _BLOCK if n_mode == 2 else block,
                4 if n_mode == 2 else warps,
            )
    else:
        degree = int(n)
        if x.is_contiguous():
            _p_flat_kernel[grid](
                x, x, out, numel, degree, N_MODE=0, BLOCK=block, num_warps=warps
            )
        else:
            _strided_launch(x, x, out, numel, degree, 0, block, warps)

    return out


def special_legendre_polynomial_p(x: torch.Tensor, n) -> torch.Tensor:
    logger.debug("GEMS SPECIAL_LEGENDRE_POLYNOMIAL_P")
    return _run(x, n)
